import{_ as i,C as n,o as r,c as d,j as t,a as l,G as a,a7 as p}from"./chunks/framework.BvFspj3b.js";const w=JSON.parse('{"title":"Solution Layout","description":"Responsibilities and dependencies of each project","frontmatter":{"title":"Solution Layout","description":"Responsibilities and dependencies of each project"},"headers":[],"relativePath":"en/dev/getting-started/solution-layout.md","filePath":"en/dev/getting-started/solution-layout.md"}'),c={name:"en/dev/getting-started/solution-layout.md"};function h(u,e,g,m,b,v){const s=n("ArticleMetadata"),o=n("HelpUsImprove");return r(),d("div",null,[e[0]||(e[0]=t("h1",{id:"solution-layout",tabindex:"-1"},[l("Solution Layout "),t("a",{class:"header-anchor",href:"#solution-layout","aria-label":'Permalink to "Solution Layout"'},"​")],-1)),a(s),a(o),e[1]||(e[1]=p(`<p><code>Ink Canvas.sln</code> contains 6 projects. Two more projects exist on disk (<code>InkCanvas.PowerPointAddIn</code>, <code>InkCanvas.NativeInk.Tests</code>) that are <strong>not part of the solution</strong> and must be opened and built separately.</p><h2 id="project-overview" tabindex="-1">Project overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project overview&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Project</th><th>Target framework</th><th>Output</th><th>Responsibility</th></tr></thead><tbody><tr><td><strong>InkCanvasForClass</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>WinExe</td><td>The main application. All UI, inking, PowerPoint integration, automation, and the plugin host live here</td></tr><tr><td><strong>InkCanvas.PluginSdk</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>Library + NuGet</td><td>The plugin SDK. Interfaces and host service abstractions that plugin projects reference</td></tr><tr><td><strong>InkCanvas.Controls</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>Library + NuGet</td><td>WPF controls shared by the host and plugins (toolbar buttons, color pickers, settings cards, popup shells)</td></tr><tr><td><strong>InkCanvas.IACoreHelper</strong></td><td><strong>.NET Framework 4.7.2</strong></td><td>Exe (x86)</td><td>Out-of-process helper providing IACore ink shape and text recognition for the main application</td></tr><tr><td><strong>InkCanvas.SettingsTreeView</strong></td><td><code>net6.0-windows10.0.19041.0</code></td><td>WinExe</td><td>Standalone utility for browsing the settings structure as a tree</td></tr><tr><td><strong>InkCanvas.PPTAgent.Contracts</strong></td><td><code>netstandard2.0</code></td><td>Library</td><td>IPC contracts between the main application and the PowerPoint VSTO add-in</td></tr></tbody></table><p>Not in the solution:</p><table tabindex="0"><thead><tr><th>Project</th><th>Target framework</th><th>Notes</th></tr></thead><tbody><tr><td><strong>InkCanvas.PowerPointAddIn</strong></td><td>.NET Framework 4.7.2 (VSTO)</td><td>PowerPoint add-in that collects slideshow state and pushes it to the main application</td></tr><tr><td><strong>InkCanvas.NativeInk.Tests</strong></td><td>—</td><td>Tests related to native inking</td></tr></tbody></table><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>InkCanvasForClass (main application)</span></span>
<span class="line"><span>  ├─&gt; InkCanvas.PluginSdk</span></span>
<span class="line"><span>  ├─&gt; InkCanvas.Controls</span></span>
<span class="line"><span>  └─&gt; InkCanvas.PPTAgent.Contracts</span></span>
<span class="line"><span></span></span>
<span class="line"><span>InkCanvas.PowerPointAddIn (VSTO, built separately)</span></span>
<span class="line"><span>  └─&gt; InkCanvas.PPTAgent.Contracts</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p><code>InkCanvas.IACoreHelper</code> and <code>InkCanvas.SettingsTreeView</code> are both standalone executables. They are not referenced by the main application and are used through inter-process communication or run by hand.</p><h2 id="why-the-framework-versions-differ" tabindex="-1">Why the framework versions differ <a class="header-anchor" href="#why-the-framework-versions-differ" aria-label="Permalink to &quot;Why the framework versions differ&quot;">​</a></h2><p>Three target frameworks coexist, each for a reason:</p><ul><li><strong>The main application uses net6.0-windows</strong>: it needs WPF, WinRT ink analysis (<code>InkAnalyzer</code>), and modern .NET performance.</li><li><strong>IACoreHelper uses .NET Framework 4.7.2 + x86</strong>: the native IACore library is a 32-bit COM component. Loading it directly would lock the main application into 32-bit. Splitting it into a separate x86 process keeps the main application AnyCPU/64-bit, and the two communicate over a named pipe plus shared memory.</li><li><strong>PPTAgent.Contracts uses netstandard2.0</strong>: it must be referenced by both the net6 main application and the .NET Framework 4.7.2 VSTO add-in, and netstandard2.0 is the common denominator.</li><li><strong>PowerPointAddIn uses .NET Framework 4.7.2</strong>: the VSTO add-in model does not support .NET 6.</li></ul><h2 id="inside-the-main-application" tabindex="-1">Inside the main application <a class="header-anchor" href="#inside-the-main-application" aria-label="Permalink to &quot;Inside the main application&quot;">​</a></h2><p>How <code>Ink Canvas/</code> is organized:</p><table tabindex="0"><thead><tr><th>Directory</th><th>Contents</th></tr></thead><tbody><tr><td><code>Automation/</code></td><td>The automation engine. Trigger/Rule/Action three-stage model, see <a href="/website/en/dev/core/automation">Automation engine</a></td></tr><tr><td><code>Controls/</code></td><td>Embedded WPF controls. <code>Toolbar/</code> holds the toolbar system, <code>Popups/</code> holds the per-tool popup layers</td></tr><tr><td><code>Helpers/</code></td><td>The largest area (around 105 files). Ink smoothing and recognition, PowerPoint integration, performance monitoring, window management, camera, cloud upload, and more</td></tr><tr><td><code>Plugins/</code></td><td>The plugin host implementation. <code>PluginManager.cs</code> is the core</td></tr><tr><td><code>Windows/</code></td><td>Individual standalone windows (settings, splash screen, and so on)</td></tr><tr><td><code>Resources/</code></td><td>Icons, images, fonts, and other resources</td></tr></tbody></table><p><code>MainWindow</code> is split across multiple partial files, see <a href="/website/en/dev/core/mainwindow">Main window</a>.</p><h2 id="where-configuration-lives" tabindex="-1">Where configuration lives <a class="header-anchor" href="#where-configuration-lives" aria-label="Permalink to &quot;Where configuration lives&quot;">​</a></h2><p>All runtime configuration sits under the <strong>application directory</strong> (not <code>%AppData%</code>):</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;application directory&gt;/</span></span>
<span class="line"><span>├── Configs/</span></span>
<span class="line"><span>│   ├── Settings.json          # main settings</span></span>
<span class="line"><span>│   └── disabled_plugins.json  # list of disabled plugins</span></span>
<span class="line"><span>├── Plugins/                    # installed plugins</span></span>
<span class="line"><span>├── PluginPackages/            # .icpx packages waiting to be installed</span></span>
<span class="line"><span>├── PluginConfigs/             # per-plugin configuration</span></span>
<span class="line"><span>├── PluginLogs/                # plugin logs</span></span>
<span class="line"><span>├── Logs/                       # main application logs</span></span>
<span class="line"><span>└── Crashes/                    # crash dumps</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">The cost of being portable</p><p>Keeping configuration in the application directory makes the software portable, but if it is installed into <code>C:\\Program Files\\</code> without write permission, saving configuration will fail. This is a deliberate trade-off — keep it in mind when making changes.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./build-and-run">Build and run</a> — versioning, CI, packaging</li><li><a href="./contributing">Contributing</a> — submission conventions</li></ul>`,21))])}const f=i(c,[["render",h]]);export{w as __pageData,f as default};
